<?php
namespace App\Services;
use App\Models\{TransportService,TransportSetting};use Illuminate\Database\Eloquent\Builder;use Illuminate\Support\Facades\DB;
class TransportAnalyticsService {
 public function query(int$company,array$f):Builder{$q=TransportService::query()->where('transport_services.company_id',$company);$q->whereBetween('transport_services.service_date',[$f['from'],$f['to']]);foreach(['transport_route_id','planned_vehicle_id','planned_driver_id','planned_monitor_id','service_type','shift','status']as$key)if(!empty($f[$key]))$q->where('transport_services.'.$key,$f[$key]);return$q;}
 public function summary(int$company,array$f):array{$setting=TransportSetting::where('company_id',$company)->first();$dep=(int)($setting?->departure_tolerance_minutes??10);$arr=(int)($setting?->arrival_tolerance_minutes??10);$base=$this->query($company,$f);$applicable=(clone$base)->where('status','!=','cancelled')->count();$closed=(clone$base)->where('status','closed')->count();$departures=(clone$base)->whereNotNull('actual_start_at');$arrivals=(clone$base)->whereNotNull('actual_arrival_at');$departureCount=(clone$departures)->count();$arrivalCount=(clone$arrivals)->count();$departureOnTime=(clone$departures)->whereRaw('TIMESTAMPDIFF(MINUTE, scheduled_start_at, actual_start_at) <= ?',[$dep])->count();$arrivalOnTime=(clone$arrivals)->whereRaw('TIMESTAMPDIFF(MINUTE, scheduled_arrival_at, actual_arrival_at) <= ?',[$arr])->count();$avgDeparture=(clone$departures)->selectRaw('AVG(TIMESTAMPDIFF(SECOND, scheduled_start_at, actual_start_at))/60 average')->value('average');$avgArrival=(clone$arrivals)->selectRaw('AVG(TIMESTAMPDIFF(SECOND, scheduled_arrival_at, actual_arrival_at))/60 average')->value('average');$capacity=(clone$base)->whereNotNull('actual_vehicle_id')->join('transport_vehicles','transport_vehicles.id','=','transport_services.actual_vehicle_id')->selectRaw('COALESCE(SUM(transport_vehicles.capacity),0) capacity')->value('capacity');$ids=(clone$base)->select('transport_services.id');$transported=DB::table('transport_service_passengers')->whereIn('transport_service_id',$ids)->whereIn('status',['boarded','completed'])->count();$expected=DB::table('transport_service_passengers')->whereIn('transport_service_id',(clone$base)->select('transport_services.id'))->where('expected',1)->where('status','!=','excluded')->count();$absent=DB::table('transport_service_passengers')->whereIn('transport_service_id',(clone$base)->select('transport_services.id'))->where('status','absent')->count();$issues=DB::table('transport_service_issues')->where('company_id',$company)->whereBetween(DB::raw('DATE(occurred_at)'),[$f['from'],$f['to']])->count();$servicesWithIssue=DB::table('transport_service_issues')->where('company_id',$company)->whereBetween(DB::raw('DATE(occurred_at)'),[$f['from'],$f['to']])->distinct('transport_service_id')->count('transport_service_id');$started=(clone$base)->whereNotNull('actual_start_at')->count();return['scheduled'=>(clone$base)->count(),'applicable'=>$applicable,'closed'=>$closed,'in_progress'=>(clone$base)->where('status','in_progress')->count(),'pending'=>(clone$base)->whereIn('status',['draft','scheduled','ready','preoperational','arrived'])->count(),'cancelled'=>(clone$base)->where('status','cancelled')->count(),'interrupted'=>(clone$base)->where('status','interrupted')->count(),'execution'=>$this->ratio($closed,$applicable),'departure_punctuality'=>$this->ratio($departureOnTime,$departureCount),'arrival_punctuality'=>$this->ratio($arrivalOnTime,$arrivalCount),'avg_departure_diff'=>$avgDeparture===null?null:round((float)$avgDeparture,1),'avg_arrival_diff'=>$avgArrival===null?null:round((float)$avgArrival,1),'capacity_utilization'=>$this->ratio($transported,(int)$capacity),'passenger_absence'=>$this->ratio($absent,$expected),'transported'=>$transported,'capacity'=>(int)$capacity,'issues'=>$issues,'services_with_issue'=>$servicesWithIssue,'issue_rate'=>$this->ratio($servicesWithIssue,$started),'interruption_rate'=>$this->ratio((clone$base)->where('status','interrupted')->count(),$started),'vehicle_changes'=>(clone$base)->whereNotNull('actual_vehicle_id')->whereColumn('actual_vehicle_id','!=','planned_vehicle_id')->count(),'driver_changes'=>(clone$base)->whereNotNull('actual_driver_id')->whereColumn('actual_driver_id','!=','planned_driver_id')->count()];}
 public function charts(int$company,array$f):array{$base=$this->query($company,$f);$states=(clone$base)->select('status',DB::raw('COUNT(*) total'))->groupBy('status')->pluck('total','status');$issues=DB::table('transport_service_issues')->where('company_id',$company)->whereBetween(DB::raw('DATE(occurred_at)'),[$f['from'],$f['to']])->select('issue_type',DB::raw('COUNT(*) total'))->groupBy('issue_type')->pluck('total','issue_type');$routes=(clone$base)->select('route_name_snapshot',DB::raw('COUNT(*) total'))->groupBy('route_name_snapshot')->orderByDesc('total')->limit(10)->pluck('total','route_name_snapshot');return compact('states','issues','routes');}
 public function byRoute(int$company,array$f){$setting=TransportSetting::where('company_id',$company)->first();$dep=(int)($setting?->departure_tolerance_minutes??10);$arr=(int)($setting?->arrival_tolerance_minutes??10);return$this->query($company,$f)->leftJoin('transport_service_issues as i','i.transport_service_id','=','transport_services.id')->select('transport_services.transport_route_id','transport_services.route_name_snapshot',DB::raw('COUNT(DISTINCT transport_services.id) services'))->selectRaw('SUM(CASE WHEN actual_start_at IS NOT NULL THEN 1 ELSE 0 END) departures, SUM(CASE WHEN actual_start_at IS NOT NULL AND TIMESTAMPDIFF(MINUTE,scheduled_start_at,actual_start_at) <= ? THEN 1 ELSE 0 END) departures_on_time',[$dep])->selectRaw('SUM(CASE WHEN actual_arrival_at IS NOT NULL THEN 1 ELSE 0 END) arrivals, SUM(CASE WHEN actual_arrival_at IS NOT NULL AND TIMESTAMPDIFF(MINUTE,scheduled_arrival_at,actual_arrival_at) <= ? THEN 1 ELSE 0 END) arrivals_on_time',[$arr])->selectRaw('COUNT(i.id) issues')->groupBy('transport_services.transport_route_id','transport_services.route_name_snapshot')->get();}
 private function ratio(int|float$n,int|float$d):?float{return$d>0?round($n/$d*100,1):null;}
}
